pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 _val1, uint256 _val2, uint256 _lockTime, uint256 _am) public {
        // Ensure _val1 and _val2 are different to test initialization guard
        vm.assume(_val1 != _val2);
        vm.assume(_lockTime > 0); // Ensure lock time set
        vm.assume(_am > 0 && _am <= address(this).balance);

        // Set MinSum to _val1
        c.SetMinSum(_val1);

        // Initialize the contract
        c.Initialized();

        // Attempt to set MinSum to _val2 - should fail in reference but succeed in mutant
        // We'll do this via a low-level call to capture revert
