        c.Put{value: _am}(_lockTime);

        // Advance time beyond unlock
        vm.warp(block.timestamp + _lockTime + 1);

        // Call Collect
        c.Collect(_am);

        // The general rule: after Collect, MinSum must equal the value set before Initialized
        assertTrue(c.MinSum() == _val1, "MinSum should remain unchanged after Initialize");
    }
