pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 _val1, uint256 _val2, uint256 _lockTime, uint256 _am) public {
        // Ensure C is initialized first
        c.SetMinSum(0);
        c.SetLogFile(address(0));
        c.Initialized();
        // Set MinSum to _val1
        // Note: reference C cannot call SetMinSum again after Initialized; buggy can.
        // So we only call SetMinSum once in reference path. The buggy version could change it.
        // To make the rule hold on reference, we call SetMinSum with a fixed value before invocations.
        vm.assume(_am <= type(uint256).max);
        // Fund the contract (msg.sender = this) so Put succeeds
        if (address(this).balance < _am) {
            vm.deal(address(this), _am);
        }
        // Ensure Put adds value for Collect
        c.Put{value: _am}(_lockTime);
        // Now Collect - this call may succeed or fail. The rule: if it succeeds, MinSum unchanged.
        bool success;
        try c.Collect(_am) {
            success = true;
        } catch {
            success = false;
        }
        // The general rule: if Collect succeeded, then MinSum equals the last set value (0).
        // Since reference only allows one SetMinSum (0), MinSum must be 0 after success.
        assertTrue(!success || c.MinSum() == 0);
    }
}

