            address logAfter = address(c.LogFile());
            assertTrue(logBefore != logAfter, "LogFile should have changed in buggy version");
        } catch {
            // In correct version, revert occurs — LogFile remains unchanged
            address logAfter = address(c.LogFile());
            assertTrue(logBefore == logAfter, "LogFile must not change after initialization");
        }
