pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public { c = new C(); }

    function testFuzz_property(
        address caller,
        uint256 initialUnlockTime,
        uint256 putValue,
        uint256 lockTime,
        uint256 minSum,
        uint256 collectAmount,
        uint256 collectTime
    ) public {
        // Bound inputs to avoid overflow and ensure sensible test conditions
        putValue = bound(putValue, 0, 1e18);
        lockTime = bound(lockTime, 0, 1000 days);
        minSum = bound(minSum, 0, 1e18);
        collectAmount = bound(collectAmount, 0, 1e18);
        collectTime = bound(collectTime, 0, 2000 days);
        initialUnlockTime = bound(initialUnlockTime, 0, 1000 days);

        // Setup: initialize the contract and set MinSum
        c.SetMinSum(minSum);
        c.Initialized();

        // Fund caller and make an initial Put to create a holder
        vm.deal(caller, 1e20);
        vm.prank(caller);
        c.Put{value: putValue}(lockTime);

        // Record unlockTime before the Collect call (through public getter)
        (uint256 unlockTimeBefore, ) = c.Acc(caller);

        // Warp to collectTime
        vm.warp(collectTime);

        // Attempt Collect with given amount (might revert due to insufficient funds from the call, but we catch it)
        uint256 balanceBefore = address(caller).balance;
        (bool success, ) = address(c).call(abi.encodeWithSelector(c.Collect.selector, collectAmount));
        if (!success) {
            // Collect reverted (e.g., due to failed call or underflow), but we still check the rule
        }

        // Get unlockTime after Collect (if it didn't revert, or even if it did via partial execution)
        (uint256 unlockTimeAfter, ) = c.Acc(caller);

        // General rule: If Collect did not change the caller's balance (i.e., no transfer occurred),
        // then unlockTime should not have decreased.
        // We check indirectly: after Collect, if the caller's balance increased by collectAmount,
        // then Collect succeeded; otherwise, it failed or the condition was not met.
        uint256 balanceAfter = address(caller).balance;
        bool didTransfer = (balanceAfter > balanceBefore);

        // If Collect didn't transfer (so condition failed or reverted), then unlockTime must not decrease.
        assertTrue(!didTransfer || unlockTimeAfter >= unlockTimeBefore);
    }
}

