import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address caller, uint256 lockTime, uint256 putAmount, uint256 collectAmount, uint256 minSum) public {
        vm.assume(caller != address(0));
        vm.assume(putAmount > 0 && putAmount <= 1e30);
        vm.assume(collectAmount > 0 && collectAmount <= putAmount);
        vm.assume(minSum > 0 && minSum <= 1e30);

        // Initialize the contract
        c.SetMinSum(minSum);
        c.Initialized();

        // Simulate time advancement
        vm.warp(block.timestamp + 1000);

        // Caller puts some amount
        vm.deal(caller, putAmount);
        vm.prank(caller);
        c.Put{value: putAmount}(lockTime);

        // Record balance before Collect
